create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('sumber','pengolah','dlh','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.submission_status as enum ('submitted','matching','offered','accepted','en_route','weighed','completed','expired','rejected','cancelled','disputed'); exception when duplicate_object then null; end $$;
create table if not exists public.cities(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,enabled boolean not null default false);
insert into cities(code,name,enabled) values('semarang','Kota Semarang',true) on conflict(code) do update set enabled=true;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,city_id uuid references cities(id),name text not null,email text,phone text,primary_role public.app_role not null default 'sumber',created_at timestamptz not null default now());
create table if not exists public.processor_profiles(id uuid primary key references profiles(id) on delete cascade,display_name text not null,processor_type text not null,status text not null default 'pending',materials text[] not null default '{}',total_capacity_kg numeric not null default 0,available_capacity_kg numeric not null default 0,service_radius_km numeric not null default 10,minimum_pickup_kg numeric not null default 1,administrative_area text not null default '',district text not null default '',latitude numeric,longitude numeric,evidence_path text,updated_at timestamptz not null default now());
create table if not exists public.submissions(id uuid primary key default gen_random_uuid(),city_id uuid not null references cities(id),source_user_id uuid not null references profiles(id),selected_processor_id uuid references processor_profiles(id),material_category text not null check(material_category in('organik','anorganik')),material_subtype text not null default '',description text not null default '',estimated_weight_kg numeric not null check(estimated_weight_kg>0),actual_weight_kg numeric,pickup_window tstzrange,administrative_area text not null default '',precise_latitude numeric,precise_longitude numeric,status public.submission_status not null default 'submitted',cancellation_reason text,dispute_reason text,formula_version text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.match_candidates(id uuid primary key default gen_random_uuid(),submission_id uuid not null references submissions(id) on delete cascade,processor_id uuid not null references processor_profiles(id),rank smallint not null check(rank between 1 and 3),compatibility_score numeric not null,distance_score numeric not null,capacity_score numeric not null,reference_value_score numeric not null default 0,minimum_volume_score numeric not null default 0,total_score numeric not null,unique(submission_id,processor_id),unique(submission_id,rank));
create table if not exists public.offers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references submissions(id) on delete cascade,processor_id uuid not null references processor_profiles(id),candidate_rank smallint not null,status text not null default 'pending',expires_at timestamptz not null,rejection_reason text,created_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),submission_id uuid unique not null references submissions(id),processor_id uuid not null references processor_profiles(id),actual_weight_kg numeric,weighing_evidence_path text,source_confirmed_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.point_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),transaction_id uuid references transactions(id),entry_type text not null,points integer not null,description text not null,status text not null default 'posted',created_at timestamptz not null default now());
create table if not exists public.redeem_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),points integer not null check(points>0),description text not null,status text not null default 'submitted',reviewed_by uuid references profiles(id),review_reason text,created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id),title text not null,body text not null,kind text not null,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.content(id uuid primary key default gen_random_uuid(),author_id uuid references profiles(id),title text not null,summary text not null default '',body text not null,status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),organizer_id uuid references profiles(id),title text not null,organizer text not null,date timestamptz not null,location text not null,status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.event_participation(event_id uuid references events(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(event_id,user_id));
create table if not exists public.formula_versions(id uuid primary key default gen_random_uuid(),version text unique not null,points_per_kg numeric not null default 10,emissions_factor numeric not null default 1.4,active boolean not null default false);
create table if not exists public.baselines(id uuid primary key default gen_random_uuid(),city_id uuid not null references cities(id),month date not null,target_kg numeric not null default 0,formula_version_id uuid references formula_versions(id),unique(city_id,month));
create table if not exists public.audit_events(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare requested text; safe_role public.app_role; begin requested:=lower(coalesce(new.raw_user_meta_data->>'primary_role','sumber')); safe_role:=case when requested='pengolah' then 'pengolah'::public.app_role else 'sumber'::public.app_role end; insert into profiles(id,name,email,primary_role) values(new.id,coalesce(new.raw_user_meta_data->>'name','Pengguna'),new.email,safe_role) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create index if not exists submissions_user_created on submissions(source_user_id,created_at desc); create index if not exists submissions_status on submissions(status,city_id); create index if not exists ledger_user on point_ledger(user_id,created_at desc);
alter table cities enable row level security; alter table profiles enable row level security; alter table processor_profiles enable row level security; alter table submissions enable row level security; alter table match_candidates enable row level security; alter table offers enable row level security; alter table transactions enable row level security; alter table point_ledger enable row level security; alter table redeem_requests enable row level security; alter table notifications enable row level security; alter table content enable row level security; alter table events enable row level security; alter table event_participation enable row level security; alter table baselines enable row level security; alter table audit_events enable row level security;
create or replace function public.is_role(r public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and primary_role=r); $$;
do $$ begin drop policy if exists cities_read on public.cities; drop policy if exists profiles_read on public.profiles; drop policy if exists profiles_insert on public.profiles; drop policy if exists profiles_update on public.profiles; drop policy if exists processors_read on public.processor_profiles; drop policy if exists processors_manage on public.processor_profiles; drop policy if exists submissions_read on public.submissions; drop policy if exists submissions_insert on public.submissions; drop policy if exists submissions_update on public.submissions; drop policy if exists ledger_read on public.point_ledger; drop policy if exists redeem_read on public.redeem_requests; drop policy if exists redeem_insert on public.redeem_requests; drop policy if exists notifications_user on public.notifications; drop policy if exists content_read on public.content; drop policy if exists events_read on public.events; drop policy if exists participation_user on public.event_participation; end $$;
create policy cities_read on cities for select using(enabled or is_role('admin')); create policy profiles_read on profiles for select using(id=auth.uid() or is_role('admin')); create policy profiles_insert on profiles for insert with check(id=auth.uid() and primary_role in ('sumber','pengolah')); create policy profiles_update on profiles for update using(id=auth.uid()); create policy processors_read on processor_profiles for select using(status='approved' or id=auth.uid() or is_role('admin')); create policy processors_manage on processor_profiles for all using(id=auth.uid() or is_role('admin')) with check(id=auth.uid() or is_role('admin')); create policy submissions_read on submissions for select using(source_user_id=auth.uid() or selected_processor_id=auth.uid() or is_role('admin')); create policy submissions_insert on submissions for insert with check(source_user_id=auth.uid()); create policy submissions_update on submissions for update using(source_user_id=auth.uid() or selected_processor_id=auth.uid() or is_role('admin')); create policy ledger_read on point_ledger for select using(user_id=auth.uid() or is_role('admin')); create policy redeem_read on redeem_requests for select using(user_id=auth.uid() or is_role('admin')); create policy redeem_insert on redeem_requests for insert with check(user_id=auth.uid()); create policy notifications_user on notifications for all using(user_id=auth.uid() or is_role('admin')); create policy content_read on content for select using(status='approved' or author_id=auth.uid() or is_role('admin')); create policy events_read on events for select using(status='approved' or organizer_id=auth.uid() or is_role('admin')); create policy participation_user on event_participation for all using(user_id=auth.uid() or is_role('admin'));
create or replace function public.transition_submission(p_submission_id uuid,p_next_status text,p_reason text default null,p_actual_weight_kg numeric default null) returns submissions language plpgsql security definer set search_path=public as $$ declare old_status submission_status; result submissions; begin select status into old_status from submissions where id=p_submission_id for update; if old_status is null then raise exception 'submission_not_found'; end if; if not ((old_status::text='submitted' and p_next_status='matching') or (old_status::text='matching' and p_next_status in('offered','cancelled')) or (old_status::text='offered' and p_next_status in('accepted','rejected','expired','cancelled')) or (old_status::text='accepted' and p_next_status in('en_route','cancelled')) or (old_status::text='en_route' and p_next_status='weighed') or (old_status::text='weighed' and p_next_status in('completed','disputed')) or (old_status::text='disputed' and p_next_status='completed')) then raise exception 'invalid_transition'; end if; update submissions set status=p_next_status::submission_status,actual_weight_kg=coalesce(p_actual_weight_kg,actual_weight_kg),cancellation_reason=case when p_next_status='cancelled' then p_reason else cancellation_reason end,dispute_reason=case when p_next_status='disputed' then p_reason else dispute_reason end,updated_at=now() where id=p_submission_id returning * into result; insert into audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'transition','submission',p_submission_id,jsonb_build_object('from',old_status,'to',p_next_status)); return result; end; $$;
create or replace function public.approve_redeem(p_request_id uuid,p_approve boolean,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$ declare request redeem_requests; begin if not is_role('admin') then raise exception 'admin_required'; end if; select * into request from redeem_requests where id=p_request_id for update; if request.status <> 'submitted' then return; end if; if p_approve then update redeem_requests set status='approved',reviewed_by=auth.uid(),review_reason=p_reason where id=p_request_id; insert into point_ledger(user_id,entry_type,points,description,status) values(request.user_id,'redeem',-request.points,request.description,'posted'); else update redeem_requests set status='rejected',reviewed_by=auth.uid(),review_reason=p_reason where id=p_request_id; end if; insert into audit_events(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'redeem_review','redeem_request',p_request_id,jsonb_build_object('approved',p_approve)); end; $$;
-- Schedule this function with pg_cron/Edge scheduler. Facts remain while precise data expires.
create or replace function public.retention_cleanup() returns void language sql security definer set search_path=public as $$ update submissions set precise_latitude=null,precise_longitude=null where status='completed' and updated_at < now()-interval '90 days'; $$;
